<template><div class="validation-panel" data-testid="validation-panel"><div v-if="!store.validation" class="dock-empty">尚未运行验证 <el-button size="small" :disabled="!store.scene.robotId" @click="store.validate()">立即验证</el-button></div><template v-else><div class="validation-summary"><b :class="store.validation.errors?'bad':'good'">{{store.validation.errors}} 错误</b><b>{{store.validation.warnings}} 警告</b><span>{{store.validation.exportReady?'可导出':'需要修复'}}</span></div><div class="issues"><button v-for="issue in store.validation.diagnostics" :key="issue.code+issue.subject"><b :class="issue.severity.toLowerCase()">{{issue.severity}}</b><span>{{issue.message}}</span><small>{{issue.subject}}</small></button></div></template></div></template>
